def trajectory_display(frames):

    mh6 = DexHandControl(port="/dev/ttyUSB0", baudrate=115200)
   
    
    
    try:
        if not mh6.start_persistent_connection():
            print("ERROR: failed to start persistent Modbus connection")
            return 1
        print("Persistent Modbus connection started. Sending commands...")
        mh6.clear_error(1)
        mh6.clear_error(2)
        mh6.clear_error(3)
        mh6.clear_error(4)
        mh6.clear_error(5)
        mh6.free_all()  # Start from a known state.
        time.sleep(1)  # Wait a moment for the hand to respond to the free command.
        print("THUMB")
        for f in frames:
            finger_values = [
                f["low_dim"]["u_thumb"],
                0,
                0,
                0,
                0,
            ]

            print("curl_norm finger values:", finger_values)
            print(mh6.map_finger_positions(finger_values))

            palm_values = [
                0.0,
                0.0,
                0.0,
            ]

            # print("palm values:", palm_values)

            mh6.move_hand_normalized(
                finger_ids=[1, 2, 3, 4, 5],
                finger_values=finger_values,
                palm_ids=[1, 2, 3],
                palm_values=palm_values,
                palm_times=[50, 50, 50],
                wait_status=False,
            )

            time.sleep(0.05)
        

        print("INDEX")
        for f in frames:
            # finger_values = [
            #     0,
            #     f["low_dim"]["u_index"],
            #     0,
            #     0,
            #     0,
            # ]
            finger_values = [
                0,
                f["low_dim"]["u_thumb"],
                0,
                0,
                0,
            ]

            print("curl_norm finger values:", finger_values)
            print(mh6.map_finger_positions(finger_values))


            palm_values = [
                0.0,
                0.0,
                0.0,
            ]

            # print("palm values:", palm_values)

            mh6.move_hand_normalized(
                finger_ids=[1, 2, 3, 4, 5],
                finger_values=finger_values,
                palm_ids=[1, 2, 3],
                palm_values=palm_values,
                palm_times=[50, 50, 50],
                wait_status=False,
            )

            time.sleep(0.05)
        print("MIDDLE")
        
        for f in frames:
            finger_values = [
                0,
                0,
                f["low_dim"]["u_thumb"],
                0,
                0,
            ]

            print("curl_norm finger values:", finger_values)
            print(mh6.map_finger_positions(finger_values))


            palm_values = [
                0.0,
                0.0,
                0.0,
            ]

            # print("palm values:", palm_values)

            mh6.move_hand_normalized(
                finger_ids=[1, 2, 3, 4, 5],
                finger_values=finger_values,
                palm_ids=[1, 2, 3],
                palm_values=palm_values,
                palm_times=[50, 50, 50],
                wait_status=False,
            )

            time.sleep(0.05)
        print("RING")
        
        for f in frames:
            finger_values = [
                0,
                0,
                0,
                f["low_dim"]["u_thumb"],
                0,
            ]

            print("curl_norm finger values:", finger_values)
            print(mh6.map_finger_positions(finger_values))


            palm_values = [
                0.0,
                0.0,
                0.0,
            ]

            # print("palm values:", palm_values)

            mh6.move_hand_normalized(
                finger_ids=[1, 2, 3, 4, 5],
                finger_values=finger_values,
                palm_ids=[1, 2, 3],
                palm_values=palm_values,
                palm_times=[50, 50, 50],
                wait_status=False,
            )

            time.sleep(0.05)
        print("LITTLE")
        
        for f in frames:
            finger_values = [
                0,
                0,
                0,
                0,
                f["low_dim"]["u_thumb"],
            ]

            print("curl_norm finger values:", finger_values)
            print(mh6.map_finger_positions(finger_values))


            palm_values = [
                0.0,
                0.0,
                0.0,
            ]

            # print("palm values:", palm_values)

            mh6.move_hand_normalized(
                finger_ids=[1, 2, 3, 4, 5],
                finger_values=finger_values,
                palm_ids=[1, 2, 3],
                palm_values=palm_values,
                palm_times=[50, 50, 50],
                wait_status=False,
            )

            time.sleep(0.05)
        
        mh6.free_all()
    

    except Exception as e:
        print(f"ERROR: exception while starting persistent connection: {e}")
        return 1
    
    finally:
        mh6.stop_persistent_connection()






    
    pass




